import { readFileSync, readdirSync, writeFileSync } from "node:fs";
const files = readdirSync("supabase/migrations")
  .filter((f) => f.endsWith(".sql"))
  .sort();
const sql = files.map(
  (file) =>
    "\n-- " +
    file +
    "\n" +
    readFileSync("supabase/migrations/" + file, "utf8")
      .replace(/^begin;\s*$/gm, "")
      .replace(/^commit;\s*$/gm, ""),
);
writeFileSync(
  "supabase/INSTALL.sql",
  "-- Initial installation in the independent OpoPlan project only.\n-- Generated by npm run schema:bundle; do not apply again to an installed database.\nbegin;\n" +
    sql.join("\n") +
    "\ncommit;\n",
);
